template <typename T>
class Stack {
private:
    struct Node {
        T item;
        Node* next;
        Node(T value, Node* link = nullptr) : item(value), next(link) {}
    };
    Node* head;
public:
    Stack() : head(nullptr) {}
    // This object owns its nodes. Disable shallow copying.
    Stack(const Stack&) = delete;
    Stack& operator=(const Stack&) = delete;
    ~Stack() {
        while (head != nullptr) {
            Node* old = head;
            head = head->next;
            delete old;
        }
    }
    bool isEmpty() const { return head == nullptr; }
    void push(T item) { head = new Node(item, head); }
    T top() const {
        if (isEmpty()) throw runtime_error("Empty stack");
        return head->item;
    }
    T pop() {
        if (isEmpty()) throw runtime_error("Empty stack");
        Node* old = head;
        T value = old->item;
        head = head->next;
        delete old;
        return value;
    }
};

