#include <stdexcept>
using namespace std;

template <typename T>
class List {
private:
    struct Node {
        T item;
        Node* next;
        Node(T value, Node* link = nullptr) : item(value), next(link) {}
    };
    Node* head;
    Node* tail;
public:
    List() : head(nullptr), tail(nullptr) {}
    // This object owns its nodes. Disable shallow copying.
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        while (head != nullptr) {
            Node* old = head;
            head = head->next;
            delete old;
        }
    }
    bool isEmpty() const { return head == nullptr; }
    void addToTail(T item) {
        Node* node = new Node(item);
        if (isEmpty()) head = node;
        else tail->next = node;
        tail = node;
    }
    void addToHead(T item) {
        head = new Node(item, head);
        if (tail == nullptr) tail = head;
    }
    T deleteFromHead() {
        if (isEmpty()) throw runtime_error("Empty list");
        Node* old = head;
        T value = old->item;
        head = head->next;
        if (head == nullptr) tail = nullptr;
        delete old;
        return value;
    }
    int size() const {
        int count = 0;
        for (Node* p = head; p != nullptr; p = p->next) ++count;
        return count;
    }
};

